import bisect

def suggested_products(products, search_word):
    products.sort()                                            # sort ONCE
    result = []
    prefix = ''
    for c in search_word:
        prefix += c
        idx = bisect.bisect_left(products, prefix)               # find lower bound
        matches = []
        for i in range(idx, min(idx + 3, len(products))):
            if products[i].startswith(prefix):
                matches.append(products[i])
            else:
                break
        result.append(matches)
    return result

