import java.util.*;

public class Main {
    static List<List<String>> suggestedProducts(String[] products, String searchWord) {
        Arrays.sort(products);                                     // sort ONCE
        List<List<String>> result = new ArrayList<>();
        StringBuilder prefix = new StringBuilder();
        for (char c : searchWord.toCharArray()) {
            prefix.append(c);
            String pre = prefix.toString();
            int idx = lowerBound(products, pre);                       // find lower bound
            List<String> matches = new ArrayList<>();
            for (int i = idx; i < Math.min(idx + 3, products.length); i++) {
                if (products[i].startsWith(pre)) matches.add(products[i]); else break;
            }
            result.add(matches);
        }
        return result;
    }

    static int lowerBound(String[] arr, String target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid].compareTo(target) < 0) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

