using namespace std;

vector<vector<string>> suggestedProducts(vector<string>& products, string searchWord) {
    sort(products.begin(), products.end());                       // sort ONCE
    vector<vector<string>> result;
    string prefix;
    for (char c : searchWord) {
        prefix += c;
        auto it = lower_bound(products.begin(), products.end(), prefix);    // find lower bound
        vector<string> matches;
        for (int i = 0; i < 3 && it != products.end(); i++, ++it) {
            if (it->compare(0, prefix.size(), prefix) == 0) matches.push_back(*it); else break;
        }
        result.push_back(matches);
    }
    return result;
}
